class.description:
A host creates one by itself when its player's scene uses [constant NetwMultiplayer.SCENE_ISOLATION_OWN_WORLD], since that scene is in a [SubViewport]. [signal NetwEntity.view_activated] is emitted when the displayed scene changes.
[codeblock]
func _ready() -> void:
    var entity := NetwEntity.of(self)
    entity.view_activated.connect(_on_view_activated)

func _on_view_activated() -> void:
    $Rig/SpringArm3D/Camera3D.make_current()
[/codeblock]
